mapper.select:
SELECT c.id, c.comment_type, u.avatar, u.nickname, IF(ru.nickname is null,'无',ru.nickname) as replyNickname, c.content, c.parent_id, c.like_count, c.create_time, c.update_time FROM sys_comment c LEFT JOIN sys_user u ON c.user_id = u.id LEFT JOIN sys_user ru ON c.reply_user_id = ru.id
and c.business_id = #{query.businessId}
and c.comment_type = #{query.commentType}
and u.nickname like concat('%', #{query.nickname}, '%')
and c.content like concat('%', #{query.content}, '%')
order by c.create_time desc
